key:
import Dispatch
func loadStars(done: @escaping () -> Void) {
    let sourceQueue = DispatchQueue(label: "stars.source")
    let group = DispatchGroup()
    func localSource(_ completion: @escaping () -> Void) {
        sourceQueue.async { print("Звёзды готовы"); completion() }
    }
    group.enter()
    localSource { group.leave() }
    group.notify(queue: .main) { done() }
}

«Звёзды готовы» гарантированно до done. В исходнике notify может опередить callback, потому что учёт закончен сразу после запуска.

