    // Создай worker/group, цикл enter/leave и notify на main
}

key:
import Dispatch
func refreshBirds(ids: [Int], done: @escaping () -> Void) {
    let worker = DispatchQueue(label: "birds.cards")
    let group = DispatchGroup()
    for id in ids {
        group.enter()
        worker.async { defer { group.leave() }; print(id) }
    }
    group.notify(queue: .main) { done() }
}

При [] нет печати id, done всё равно приходит асинхронно через main. Пустая партия не оставляет лишний enter.

