import Dispatch
func loadForecast(done: @escaping () -> Void) {
    let group = DispatchGroup()
    group.enter()
    let finish = { group.leave() }
    finish()
    finish()
    group.notify(queue: .main) { done() }
}

key:
import Dispatch
func loadForecast(done: @escaping () -> Void) {
    let group = DispatchGroup()
    let state = DispatchQueue(label: "forecast.finish")
    var finished = false
    group.enter()
    let finish = {
        state.sync {
            guard !finished else { return }
            finished = true
            group.leave()
        }
    }
    finish()
    finish()
    group.notify(queue: .main) { done() }
}

done приходит один раз для этой регистрации notify. Повторный finish не даёт лишнего leave; вся работа с флагом проходит через state.
